29	  shutDownSignal: ShutdownSignal = new ShutdownSignal(),
30	  emitter: typeof defaultEmitter = defaultEmitter
31	) => {
32	  initializeLogger(emitter);
33	  // Validate the whole environment before anything else, including before the
34	  // first heartbeat: a bot that reports "started" and then dies on a missing
35	  // variable looks alive to whatever is watching it.
36	  const validatedEnv = await validateEnvironment();
37	  emitter.emit(BotEvents.ENV_VALIDATED, validatedEnv.signerAddress, validatedEnv.chainIds, validatedEnv.networks);
38	  for (const warning of validatedEnv.warnings) emitter.emit(BotEvents.ENV_WARNING, warning);
