69	    const veaOutboxProvider = new FallbackProviderV5(outboxRPC, emitter);
70	    let veaOutboxLatestBlock = await veaOutboxProvider.getBlock("latest");
71	
72	    // If the watcher has already started, only check the latest epoch
73	    if (network == Network.DEVNET) {
74	      toWatch[networkKey].epochs = [Math.floor(veaOutboxLatestBlock.timestamp / routeConfig[network].epochPeriod)];
